define('SageDotCom/Utility/FaqSchema',[
    "jquery"
], function ($) {
    function FaqSchema() { }

    FaqSchema.prototype.init = function init() {
        $(document).ready(function () {
            var $faqSchemaCheckedItem = $(".score-accordion .faq-schema-checked");

            if ($faqSchemaCheckedItem.length > 0) {
                var scriptElement = document.createElement("script");
                scriptElement.type = "application/ld+json";

                var $questionText = $(".score-accordion .faq-schema-checked .panel-heading .panel-title button");
                var $answerText = $(".score-accordion .faq-schema-checked .panel-collapse .panel-body");

                var arrayMainEntity = [];

                $faqSchemaCheckedItem.each(function (index) {
                    var mainEntityObj = new Object();
                    var acceptedAnswerObj = new Object();
                    if ($questionText[index]) {
                        mainEntityObj["@type"] = "Question";
                        mainEntityObj["name"] = $questionText[index].innerText.trim();
                        arrayMainEntity.push(mainEntityObj);
                    }

                    if ($answerText[index]) {
                        acceptedAnswerObj["@type"] = "Answer";
                        acceptedAnswerObj["text"] = $answerText[index].innerText.trim();
                        mainEntityObj.acceptedAnswer = acceptedAnswerObj;
                    }
                });

                scriptElement.text = JSON.stringify({ "@context": "http://schema.org", "@type": "FAQPage", "mainEntity": arrayMainEntity });
                document.querySelector("head").appendChild(scriptElement);
            }
        });
    }


    return new FaqSchema();
});
define('SageDotCom/Utility/ProductSchema',[
    "jquery"
], function ($) {
    function ProductSchema() { }

    ProductSchema.prototype.init = function init() {
        $(document).ready(function () {

            var $prodCard = $(".sage-product-card-outer");
            if ($prodCard.length > 0) {
                var scriptElement = document.createElement("script");
                scriptElement.type = "application/ld+json";
                
                var $name = ($('meta[name="sage:products"]').attr("content") !== "") ? $('meta[name="sage:products"]').attr("content") : ($("div.navbar-brand").text().trim() !== "") ? $("div.navbar-brand").text().trim() : "" ;
                if ($name === "$name") {
                    $name = ($("div.navbar-brand").text().trim() !== "") ? $("div.navbar-brand").text().trim() : "";
                    console.error("'metadata name incorrect - $name'");
                }
                var $description = $('meta[name="sage:pagedescription"]').attr("content");
                var $priceCurrency = $('meta[name="product:pretax_price:currency"]').attr("content");
                var $price = $(".sage-product-card-price-alt");
                if (!($price && $price.length > 0))
                    $price = $(".main-price-line .price");

                var sellerObj = new Object();
                sellerObj["@type"] = "Organization";
                sellerObj["name"] = "Sage";
              
                if ($prodCard.length === 1) {
                    var price = (($price && $price.length > 0) ? $price.text() : "0.0");
                    var sku = "0000000";
                    var brandObj = new Object();
                    brandObj["@type"] = "Brand";
                    brandObj["name"] = "Sage";
                    var offerObj = new Object();
                    offerObj["@type"] = "Offer";
                    offerObj["url"] = location.toString();
                    offerObj["priceCurrency"] = ($priceCurrency) ? $priceCurrency : "";
                    offerObj["price"] = ((price.indexOf('FREE')) === 0) ? "0.00" : price;
                    offerObj["availability"] = "https://schema.org/OnlineOnly";
                    offerObj["seller"] = sellerObj;
                   
                    scriptElement.text = JSON.stringify({
                        "@context": "http://schema.org",
                        "@type": "Product",
                        "name": $name,
                        "description": $description,
                        "sku": sku,
                        "brand" : brandObj,
                        "offers": offerObj
                    });
                    document.querySelector("head").appendChild(scriptElement);
                }
                if ($prodCard.length > 1) {
                    var $titleArea = $(".sage-product-card-title-area span");
                    var $prodcartTitle = $(".sage-product-card-title");
                    var $prodcartSubTitle = $(".sage-product-card-subtitle");
                    var offersArray = [];

                    $prodCard.each(function (index) {
                        var offerObj = new Object();
                        var price = ($price[index] && $price[index].innerText.trim() !== "") ? $price[index].innerText.trim() : "0.0";
                        var titleArea = ($titleArea[index] && $titleArea[index].innerText.trim() !== "") ? $titleArea[index].innerText.trim() : "";
                        var prodcartTitle = ($prodcartTitle[index] && $prodcartTitle[index].innerText.trim() !== "") ? $prodcartTitle[index].innerText.trim() : "";
                        var prodcartSubTitle = ($prodcartSubTitle[index] && $prodcartSubTitle[index].innerText.trim() !== "") ? $prodcartSubTitle[index].innerText.trim() : "";
                        var sku = (titleArea !== "" && prodcartTitle !== "") ? titleArea + " - " + prodcartTitle : (prodcartTitle !== "" && prodcartSubTitle !== "") ? prodcartSubTitle + " - " + prodcartTitle  : "";
                        if (sku === "") {
                            sku = (titleArea !== "")
                                ? titleArea
                                : (prodcartTitle !== "")
                                ? prodcartTitle
                                : (prodcartSubTitle !== "")
                                ? prodcartSubTitle
                                : "";
                        }
                        offerObj["@type"] = "Offer";
                        offerObj["sku"] = sku;
                        offerObj["url"] = location.toString();
                        offerObj["price"] = ((price.indexOf('FREE')) === 0) ? "0.00" : price; 
                        offerObj["priceCurrency"] = ($priceCurrency) ? $priceCurrency : "";
                        offerObj["availability"] = "https://schema.org/OnlineOnly";
                        offerObj["seller"] = sellerObj;
                        offersArray.push(offerObj);
                        
                    });
                    scriptElement.text = JSON.stringify({
                        "@context": "http://schema.org",
                        "@type": "Product",
                        "name": $name,
                        "description": $description,
                        "offers": offersArray
                    });
                    document.querySelector("head").appendChild(scriptElement);
                }
            }

        });
    }

    return new ProductSchema();
});
define('SageDotCom/components/forms/AccountingForm',[
    "jquery"
], function ($) {
    function AccountingForm() { }

    var canSendOtp = true;

    function addSageAccountingFormObserver() {
        var targetNode = document.querySelector(".accounting-form").parentNode.parentNode;
        var config = { attributes: true, childList: true, subtree: true };

        // Callback function to execute when mutations are observed
        var callback = function (mutationsList, observer) {
            for (var mutation in mutationsList) {
                var mutationItem = mutationsList[mutation];
                if (mutationItem.type === "childList") {
                    if (!$(".accounting-form input[type='submit']").hasClass("with-loader")) {
                        $(".accounting-submit-form input[type='submit'].disabled").removeClass("disabled");
                        $(".accounting-submit-form input[type='submit']").removeAttr("disabled");
                        $(".accounting-form .otp-button").val($(".accounting-form-resend-msg").text());
                        $(".accounting-form-otp-sent").removeClass("hidden");
                        $(".accounting-submit-form").find(".dynamic-required").each(function () {
                            var $input = $(this);
                            $input.prop("required", true);
                            $input.next(".error").remove();
                        });
                    }

                    $(".accounting-form input[type=submit].otp-button").attr("type", "button");
                    $(".accounting-submit-form input[type='submit']").on("click", function () {
                        var parent = $(this).parent();
                        var anyErrors = parent.parent().find(".field-validation-error");
                        if ($("form").valid() === true && anyErrors.length <= 0) {
                            if (!$(this).hasClass("with-loader")) {
                                addSpinner($(this), parent);
                            }
                        }
                    });

                    $(".accounting-form .otp-button").on("click", function () {
                        //Stop OTP from being sent multiple times due to being within an observer
                        if (canSendOtp) {
                            canSendOtp = false;
                            sendOtpMsg();
                        }

                        setTimeout(function () {
                            canSendOtp = true;
                        }, 500);
                    });
                }
            }
        };

        // Create an observer instance linked to the callback function
        var observer = new MutationObserver(callback);
        // Start observing the target node for configured mutations
        observer.observe(targetNode, config);
    }
    function addSpinner(submit, context) {
        submit.addClass("with-loader");
        submit.val("");
        context.append("<div class='loader'></div>");
        var spinner = context.find(".loader");
        spinner.append("<div class='bounce bounce1'></div>");
        spinner.append("<div class='bounce bounce2'></div>");
        spinner.append("<div class='bounce bounce3'></div>");
    }
    function removeSpinner(submit, context) {
        submit.removeClass("with-loader");
        var spinner = context.find(".loader");
        spinner.remove();
    }

    function sendOtpMsg() {
        var parent = $(this).parent();
        addSpinner($(this), parent);

        var number = $(".otp-telephone").val();
        var formId = $(".accounting-form").attr("id");
        var id = formId.substring(formId.length - 36);
        var terr = $("html").attr("lang").toLowerCase();

        if (terr && terr === "en-ae") {
            terr = "en-tv";
        }

        var tokenElement = $(`#${formId} input[name="__RequestVerificationToken"]`);
        var token = tokenElement.length > 0 ? tokenElement.val() : null;
        if (token) {
            $.ajax({
                type: "POST",
                url: "/api/sitecore/SendFormData/SendOtpMsg",
                headers: {
                    "__RequestVerificationToken": token
                },
                data: {
                    phoneNumber: number,
                    formId: id,
                    territory: terr
                },
                context: this
            }).done(function (response) {
                $(".accounting-submit-form input[type='submit'].disabled").removeClass("disabled");
                $(".accounting-submit-form input[type='submit']").removeAttr("disabled");

                $(".accounting-form .otp-button").val($(".accounting-form-resend-msg").text());
                $(".accounting-form-otp-sent").removeClass("hidden");

                $(".accounting-submit-form").find(".dynamic-required").each(function () {
                    var $input = $(this);
                    $input.prop("required", true);
                    $input.next(".error").remove();
                });

                removeSpinner($(this), parent);
            }).fail(function (response) {
                $(".accounting-form .otp-button").val($(".accounting-form-resend-msg").text());
                removeSpinner($(this), parent);
            });
        }
    }

    AccountingForm.prototype.init = function init() {

        $(".accounting-submit-form input[type='submit']").on("click", function () {
            var parent = $(this).parent();
            var anyErrors = parent.parent().find(".field-validation-error");
            if ($("form").valid() === true && anyErrors.length <= 0) {
                if (!$(this).hasClass("with-loader")) {
                    addSpinner($(this), parent);
                    addSageAccountingFormObserver();
                }
            }
        });

        $(".accounting-form .otp-button").on("click", function () {
            sendOtpMsg();
        });
    }


    return new AccountingForm();
});
define('SageDotCom/Components/ProductCard/ProductCardSelection',['jquery', "eventManager"], function($, eventManager) {

    function ProductCardSelection() { }

    ProductCardSelection.prototype.checkPageCookie = function checkPageCookie() {
        if (!this.checkProductCardPersonalisationEnabled())
            return;

        const pathName = window.location.pathname;

        //read out cookie value and set the product card
        let cookieValue = getCookie(`${pathName}_productCardSelection`);
        if(cookieValue != null) {   
            let obj = JSON.parse(cookieValue);
            for (const card in obj) {
                const $card = $(`.sage-product-card[data-pid='${card}'], .sage-product-card-alt[data-pid='${card}']`);
                let objectValues = obj[card];
                if (objectValues.dropdownIndex != null) {

                    setTimeout(function () {
                        $card.find('.sage-product-card-tooltip-icon').each(function () {
                            $(this).tooltip('destroy');
                        });
                    }, 10);

                    $card.find(".price-ddl").prop('selectedIndex',objectValues.dropdownIndex);
                    const cardContainer = $card.parent().attr("id");

                    eventManager.trigger('productCardPriceChange:' + cardContainer, $("#" + cardContainer));
                    eventManager.trigger("product card detail event", "dropdown", "", false, "", objectValues.dropdownIndex);

                    setTimeout(function () {
                        $card.find('.sage-product-card-tooltip tr').each(function () {
                            if ($(this).find('span').is(':empty')) {
                                $(this).css('display', 'none');
                            } else {
                                $(this).css('display', '');
                            }
                        });

                        $card.find('.sage-product-card-tooltip-icon').each(function () {
                            $(this).tooltip(
                                {
                                    html: true,
                                    placement: 'bottom',
                                    title: $('#' + $(this).data('tip')).html()
                                });
                        });

                    }, 500);
                }
                if (objectValues.checkboxSelected == true) {
                    
                    //this if is to prevent issue with when the user clicks back in browser and the checkbox is selected
                    if(!$card.find(".addon-chk").is(":checked")) {
                        $card.find(".addon-chk").click();
                    }

                }
            }
        } 
    }
    
    ProductCardSelection.prototype.setProductCardValue = function setProductCardValue(part, value, productCardId) {
        if (!this.checkProductCardPersonalisationEnabled())
            return;

        const pathName = window.location.pathname;
        const dateTime = new Date();
        let cookieValue = getCookie(`${pathName}_productCardSelection`);
        let cardSelections = {};
        dateTime.setTime(dateTime.getTime() + (7*24*60*60*1000));
        const expires = "expires="+ dateTime.toUTCString();

        let cardSelection = {
            dropdownIndex: null,
            checkboxSelected: false
        }

        //check if already saved
        if (cookieValue == null) {
            //check if value for dropdown has been saved
            if (part == "dropdown") {
                cardSelection.dropdownIndex = value;
            } else {
                cardSelection.checkboxSelected = value;
            }

            //append key value pair to the object
            Object.assign(cardSelections, {[productCardId]: cardSelection})

            document.cookie = `${pathName}_productCardSelection=${JSON.stringify(cardSelections)};${expires};path=/`;
        } else {
            let obj = JSON.parse(cookieValue);
            let currentProductCard = obj[productCardId];

            //this will update the object
            if (part == "dropdown") {
                if (currentProductCard == null) {
                    cardSelection.dropdownIndex = value;
                    Object.assign(obj, {[productCardId]: cardSelection})
                } else {
                    if (currentProductCard.dropdownIndex != value) {
                        currentProductCard.dropdownIndex = value;
                    }
                }
            } else {
                if (currentProductCard == null) {
                    cardSelection.checkboxSelected = value;
                    Object.assign(obj, {[productCardId]: cardSelection})
                } else {
                    if (currentProductCard.checkboxSelected != value) {
                        currentProductCard.checkboxSelected = value;
                    }
                }
            }
            //override the cookie with updated values
            document.cookie = `${pathName}_productCardSelection=${JSON.stringify(obj)};${expires};path=/`;
        }
    } 

    ProductCardSelection.prototype.checkProductCardPersonalisationEnabled = function checkProductCardPersonalisationEnabled() {
        return document.body.classList.contains('pc-personalisation');
    }

    const getCookie = (cname) => {
        let ca = document.cookie.split(";");
        
        for (const cookie of ca) {
            if (cookie.indexOf(cname + "=") > 0) {
                return cookie.split("=")[1];
            }
        }
        return null;
    };

    return new ProductCardSelection();
});
