        eventManager.subscribe("add-aria-labels-to-pagination",
            function () {
                var paginationPages = $(".paginationjs-pages ul li, .pagination ul.pages li, ul.pagination li");
                if (paginationPages.length > 0) {
                    paginationPages.each(function () {
                        var label = "Page";
                        var title = $(this).attr("title");
                        var pageNum = null;
                        var addPageNumToLabel = true;
                        var isCurrentPage = false;

                        if (typeof title !== undefined) {
                            if ($(this).attr("title") === "Previous page") {
                                label = "Previous Page";
                                addPageNumToLabel = false;
                            }
                            if ($(this).attr("title") === "Next page") {
                                label = "Next Page";
                                addPageNumToLabel = false;
                            }
                        }

                        if ($(this).hasClass("active")) {
                            label = "Current Page, Page";
                            isCurrentPage = true;
                        }
                        if ($(this).hasClass("prev") || $(this).hasClass("PagedList-skipToPrevious")) {
                            label = "Previous Page";
                            addPageNumToLabel = false;
                        }
                        if ($(this).hasClass("next") || $(this).hasClass("PagedList-skipToNext")) {
                            label = "Next Page";
                            addPageNumToLabel = false;
                        }
                        if ($(this).hasClass("last") || $(this).hasClass("PagedList-skipToLast")) {
                            label = "Last Page";
                            addPageNumToLabel = false;
                        }
                        if ($(this).hasClass("PagedList-skipToFirst")) {
                            label = "First Page";
                            addPageNumToLabel = false;
                        }

                        var element = $(this).children("a, span");
                        if (typeof element !== undefined) {
                            pageNum = element.text();
                            if (parseInt(pageNum) && addPageNumToLabel) {
                                label += " " + pageNum;
                            }

                            element.attr("aria-label", label);

                            if (isCurrentPage) {
                                element.attr("aria-current", "true");
                            }
                        }
                    });
                }
            });

        setTimeout(function () {
            eventManager.trigger("add-aria-labels-to-pagination");
        }, 50);

