            transformIntoDiv(highlightNavHeading, "highlight-title");
            transformIntoDiv(contentSpotSubnavHeading, "megamenu-subnav-heading-title");
            transformIntoDiv(contentSpotHeading, "megamenu-title");
            transformIntoDiv(highlightLoginHeading, "highlight-title");
