        var moveScoreBrightcoveTabsetVideo = function () {
            // you need to manaully move the score brightcove video between tabset and accordion because this component is not duplicated in sageBootstrap like the rest of the content
            // this is because the duplication was causing issues with the player and the vifdeo was not working

            // only need to run for tabset that have a brightcove video inside
            var tabsets = $(".score-tab:has(.score-brightcove-video)");

            tabsets.each(function () {
                var tabset = $(this);
                var isDesktopVisible = tabset.find(".tabAccordion-tabSet").css("display") === "none" ? false : true;
                var isMobileVisible = tabset.find(".tabAccordion-accordion").css("display") === "none" ? false : true;

                var desktopPanels = tabset.find(".tabAccordion-tabSet .tabAccordion-panel-tabSet");
                var mobilePanels = tabset.find(".tabAccordion-accordion .tabAccordion-panel-accordion");


                desktopPanels.each(function (index) {
                    var currentDesktopPanel = $(this);
                    var currentMobilePanel = $(mobilePanels.get(index));

                    var desktopVideo = currentDesktopPanel.find(".score-brightcove-video");
                    var mobileVideo = currentMobilePanel.find(".score-brightcove-video");

                    if ((desktopVideo === null || desktopVideo.length < 1) && (mobileVideo === null || mobileVideo.length < 1)) {
                        // no brightcove video to be found in either of the panels so nothing to do, go to next panel
                        return true; // jquery equivalent of continue
                    }

                    if (isDesktopVisible && (desktopVideo === null || desktopVideo.length === 0)) {
                        // unbound event listener
                        mobileVideo.closest('.collapse').off('hidden.bs.collapse.brightcove');

                        // move the video from accordion into tabset
                        var parentPlaceholder = mobileVideo.parent().attr("id").replace("-mobile", "");
                        var desktopParent = currentDesktopPanel.find("#" + parentPlaceholder);
                        desktopParent.append(mobileVideo);
                    }
                    else if (isMobileVisible && (mobileVideo === null || mobileVideo.length === 0)) {
                        // move the video from tabset into accordion
                        var parentPlaceholder = desktopVideo.parent().attr("id") + "-mobile";
                        var mobileParent = currentMobilePanel.find("#" + parentPlaceholder);
                        var collapseParent = mobileParent.closest('.collapse');
                        collapseParent.on('hidden.bs.collapse.brightcove', function (event) {
                            var brightcoveJsVideos = desktopVideo.find(".brightcove-media-container-js .video-js");
                            brightcoveJsVideos.each(function () {
                                var videoId = $(this).attr("id");
                                videojs.getPlayer(videoId).pause();
                            });
                        });
                        mobileParent.append(desktopVideo);
                    }
                });
            });
        }

