        if ($('.comparison-table-product-card .product-card-common-element div:last-child .score-button').length) {
            $('<span class="bottom-line"></span>').appendTo('.comparison-table-product-card .product-card-common-element div:last-child .score-button');
        }

        if ($('.sage-partner-search .get-location').length) {
            $('<span class="bottom-line"></span>').appendTo('.sage-partner-search .get-location');
        }
        if ($('.form-back-btn').length) {
            $('<span class="bottom-line"></span>').appendTo('.form-back-btn');
        }

        // add class to product card so it can get outline
        $('.sage-product-card-section-content-alt div.sage-product-card-promo-header-alt').each(function () {
            // need to do it for all product cards now as new suites will have 2 groups of cards, and one may need featured outline in each set
            $(this).closest('.sage-product-card-outer').addClass('featured-outline');
        });

        // remove link from footer copy button & add class so it can be targeted
        $(".score-footer a[href=''], .score-footer a[href='#'], .score-footer a[href='http://#']").addClass("sage-copy-text").removeAttr('href')

