    /*
     * Sitecore issue with SC 9 Forms - Language Fix
     */
    [].forEach.call(document.querySelectorAll('form'), function (el) {
        var attrAction = el.getAttribute("action");
        if (attrAction !== null && typeof attrAction !== typeof undefined && attrAction !== false) {
            if (attrAction.indexOf("formbuilder") >= 0) {
                if (attrAction.indexOf("sc_lang=") < 0) {
                    var sep = "?";
                    if (attrAction.indexOf("?") > 0) {
                        sep = "&";
                    }

                    var u = window.location.href;
                    var s = u.split("/");

                    if (s.length >= 4) {
                        var lang = s[3];

                        var findLang = 4;
                        while (lang == "" && s.length >= findLang + 1) {
                            lang = s[findLang];
                            findLang++;
                        }

                        //hard coded - TODO: Find the language in a different place
                        if (lang && lang.toLowerCase() === "investors")
                            lang = "en-gb";

                        if (lang && lang.toLowerCase() === "africa")
                            lang = "en-zw";

                        if (lang && lang.toLowerCase() === "en-ae")
                            lang = "en-tv";

                        if (/^.{2,3}-.{2}$|^.{2}-.{4}-.{2}$/.test(lang))
                            el.setAttribute("action", attrAction + sep + "sc_lang=" + lang);
                    }
                }
            }
        }
    });

