    function CalculateMenuPosition(dropdown) {
        if (!window.BrainJocks.EE) {
            if (!$('.score-header').hasClass('collapsed')) {
                $(dropdown).addClass('open');
                $(dropdown).children().first().attr('aria-expanded', 'true');
                if ($(dropdown).hasClass('center-positioned')) {

                    var mmWidth = $('header .score-megamenu').parent().width();

                    var listItemWidth = $(dropdown)[0].offsetWidth;
                    var listItemLeft = $(dropdown)[0].offsetLeft;
                    var ddlMenuEl = $(dropdown).find('.dropdown-menu');
                    if (ddlMenuEl) {
                        // offsetWidth can be taken only from a visible element.
                        var dropdownMenu = ddlMenuEl[0].offsetWidth;
                        if ((listItemLeft + listItemWidth / 2 + dropdownMenu / 2) >= mmWidth) {
                            var pushMargin = (mmWidth - dropdownMenu) / 2;
                        } else {
                            var pushMargin = listItemLeft + listItemWidth / 2 - dropdownMenu / 2 + 24;
                        }

                        ddlMenuEl.css('marginLeft', pushMargin + 'px');
                    }
                }
            }
        }
    }

