                if (!window.AdjustingAgnosticCards) {
                    window.AdjustingAgnosticCards = true;

                    //Header
                    $(".sage-agnostic-product-card-header").matchHeight({ byRow: true });

                    //Select box / anything above the main price line
                    $(".agnostic-product-card-pricing .non-button-section .above-price-section .selector-section").matchHeight({ byRow: true });
                    $(".agnostic-product-card-pricing .non-button-section .above-price-section").matchHeight({ byRow: true });

                    //Main price line
                    $(".agnostic-product-card-pricing .non-button-section .pricing-information").matchHeight({ byRow: true });
                    //Promo box
                    $(".agnostic-product-card-pricing .non-button-section .sage-agnostic-product-card-promo").matchHeight({ byRow: true });
                    //Add on toggle
                    $(".agnostic-product-card-pricing .non-button-section .sage-product-card-addon-alt").matchHeight({ byRow: true });

                    //Everything except the buttons
                    $(".agnostic-product-card-pricing .non-button-section").matchHeight({ byRow: true });

                    //Everything in total
                    $(".agnostic-product-card-pricing").matchHeight({ byRow: true });

                    //Footer components
                    //Footer top section
                    $(".agnostic-product-card-footer-top").matchHeight({ byRow: true });
                    //Footer bottom section
                    $(".agnostic-product-card-footer-bottom .main-footer-content").matchHeight({ byRow: true });
                    $(".agnostic-product-card-footer-bottom").matchHeight({ byRow: true });
                    
                    $(".sage-agnostic-product-card-container").matchHeight({ byRow: true });

                    window.AdjustingAgnosticCards = false;
                }
