            eventManager.subscribe("adjust-agnostic-cards", matchElementHeights);

            // use when just trying to update the heights (eg. price/promotion has loaded)
            eventManager.subscribe("refresh-agnostic-cards", deferredFunction);

            //Run the function
            matchElementHeights();
