                                    const unselectedAddon = variant !== undefined ?
                                        $addonsSection.find(`.addon[data-addon-sku='${selectedSku}'][data-variant!='${variant}'], .addon[data-addon-sku!='${selectedSku}']`)
                                        : $addonsSection.find(`.addon[data-addon-sku!='${selectedSku}']`);
                                    unselectedAddon.hide();
