                        var textContent = $(this).attr('data-remove');
                        if ($(this).parent().hasClass("switch")) {
                            $($(this).closest('label')).find('[class*="sage-product-card-addon-label"]').text(textContent);
                        } else {
                            $(this).parent().find('label').text(textContent);
                        }
